// Probe only, never merged: the mutants of planner v2, one textual change each, generated by code.
// `mutants(dir)` lists them; `write(dir, out, mutant)` writes a copy of the planner folder with that one change.
import { cpSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const FILES = ['groups.ts', 'plan.ts', 'rules.ts', 'solver.ts', 'view.ts', 'render.ts'];

/** A line that holds code, not a comment. */
const code = (line) => {
  const t = line.trim();
  return t !== '' && !t.startsWith('//') && !t.startsWith('*') && !t.startsWith('/*') && !t.startsWith('import ');
};

/** Positions of `token` in `line` outside string and template literals. */
function sites(line, token) {
  const out = [];
  let quote;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = undefined;
      continue;
    }
    if (c === "'" || c === '"' || c === '`') {
      quote = c;
      continue;
    }
    if (line.startsWith(token, i)) out.push(i);
  }
  return out;
}

const SWAPS = [
  ['comparison', ' <= ', ' < '],
  ['comparison', ' < ', ' <= '],
  ['comparison', ' >= ', ' > '],
  ['comparison', ' > ', ' >= '],
  ['equality', ' === ', ' !== '],
  ['equality', ' !== ', ' === '],
  ['logic', ' && ', ' || '],
  ['logic', ' || ', ' && '],
  ['off-by-one', ' + 1', ' + 2'],
  ['off-by-one', ' - 1', ' - 2'],
  ['constant', 'true', 'false'],
  ['constant', 'false', 'true'],
];

/** The balanced condition of `if (` at `at`, as [start, end) of its inside. */
function condition(line, at) {
  let depth = 0;
  for (let i = at + 3; i < line.length; i++) {
    if (line[i] === '(') depth++;
    else if (line[i] === ')') {
      depth--;
      if (depth === 0) return [at + 4, i];
    }
  }
  return undefined;
}

export function mutants(dir) {
  const out = [];
  for (const file of FILES) {
    const lines = readFileSync(join(dir, file), 'utf8').split('\n');
    lines.forEach((line, at) => {
      if (!code(line)) return;
      for (const [operator, from, to] of SWAPS) {
        for (const i of sites(line, from)) {
          // A whole word for constants; `<` and `>` of an arrow or a type are not comparisons.
          if (operator === 'constant' && (/\w/.test(line[i - 1] ?? '') || /\w/.test(line[i + from.length] ?? '')))
            continue;
          if (operator === 'comparison' && (line.slice(i, i + 4) === ' => ' || line[i + from.length] === '='))
            continue;
          out.push({ file, line: at + 1, operator, text: line.slice(0, i) + to + line.slice(i + from.length) });
        }
      }
      // Sort and compare: the two sides of the comparison swap.
      if (/\.sort\(|compareWeight\(|localeCompare\(/.test(line)) {
        const swapped = line
          .replace(/\b(a|b)(\b)/g, (_, side) => (side === 'a' ? '\u0000' : 'a'))
          .replaceAll('\u0000', 'b');
        if (swapped !== line) out.push({ file, line: at + 1, operator: 'order', text: swapped });
      }
      // A guard that leaves early is dropped; a condition is negated.
      if (/^\s*if \(.*\) (continue|return\b[^;]*|break);\s*$/.test(line))
        out.push({ file, line: at + 1, operator: 'drop-guard', text: '' });
      for (const i of sites(line, 'if (')) {
        const inside = condition(line, i);
        if (!inside) continue;
        const [start, end] = inside;
        out.push({
          file,
          line: at + 1,
          operator: 'negate',
          text: `${line.slice(0, start)}!(${line.slice(start, end)})${line.slice(end)}`,
        });
      }
    });
  }
  return out.map((mutant, n) => ({ ...mutant, id: `m${String(n + 1).padStart(3, '0')}` }));
}

/** A copy of the planner folder at `out` with the one change of `mutant`. */
export function write(dir, out, mutant) {
  cpSync(dir, out, { recursive: true });
  const path = join(out, mutant.file);
  const lines = readFileSync(path, 'utf8').split('\n');
  lines[mutant.line - 1] = mutant.text;
  writeFileSync(path, lines.join('\n'));
  return join(out, 'index.ts');
}

if (process.argv[2] === 'count') {
  const list = mutants(process.argv[3]);
  const by = (key) =>
    Object.entries(list.reduce((acc, m) => ({ ...acc, [m[key]]: (acc[m[key]] ?? 0) + 1 }), {}))
      .map(([k, v]) => `${k} ${v}`)
      .join(', ');
  console.log(`${list.length} mutants`);
  console.log(`by operator: ${by('operator')}`);
  console.log(`by file: ${by('file')}`);
  void readdirSync;
}
